func findPublishedRun(state *catalog.TableState, runID string, branch *catalog.Ref, base int64, baseOK bool) *catalog.Snapshot {
	if state.Main == nil {
		return nil
	}
	// Fast-forward detection. CRITICAL: require the branch to have actually
	// ADVANCED past its base. A freshly created branch sits AT base == main's
	// head, so a bare IsAncestor check is trivially true and would declare
	// every run published the instant its branch is created — before the
	// write job has done anything.
	if branch != nil && (!baseOK || branch.SnapshotID != base) &&
		state.IsAncestor(branch.SnapshotID, state.Main) {
		if s, ok := state.Snapshots[branch.SnapshotID]; ok {
			return &s
		}
		return &catalog.Snapshot{ID: branch.SnapshotID}
	}
	// Walk main's ancestry looking for the writer-stamped run-id.
	cur := state.Main.SnapshotID
	seen := map[int64]bool{}
	for !seen[cur] {
		seen[cur] = true
		s, ok := state.Snapshots[cur]
		if !ok {
			return nil
		}
		if s.Summary[SnapshotSummaryRunID] == runID {
			return &s
		}
		if s.ParentID == nil {
			return nil
		}
		cur = *s.ParentID
	}
	return nil
}

