// TestPublishedDetection is the Challenge B disambiguation: after an
// ambiguous commit, re-observation must correctly report whether the publish
// happened.
func TestPublishedDetection(t *testing.T) {
	// Case 1: commit did NOT apply — main still at 200, branch at 300.
	s := fixtureState()
	br := catalog.Ref{Name: "b", SnapshotID: 300}
	if got := findPublishedRun(s, "run123", &br, 200, true); got != nil {
		t.Fatalf("publish not applied, but detector claims snapshot %d published", got.ID)
	}

	// Case 2: commit DID apply — main fast-forwarded to 300.
	s.Main.SnapshotID = 300
	got := findPublishedRun(s, "run123", &br, 200, true)
	if got == nil || got.ID != 300 {
		t.Fatal("publish applied (branch head is main): detector must report it")
	}

	// Case 3: total amnesia — status lost AND branch already cleaned up.
	// The writer-stamped snapshot summary is the only surviving evidence.
	delete(s.Branches, "b")
	got = findPublishedRun(s, "run123", nil, 0, false)
	if got == nil || got.ID != 300 {
		t.Fatal("run-id summary stamp in main lineage must be sufficient on its own")
	}

	// Case 4: different run's stamp must not match.
	if findPublishedRun(s, "other-run", nil, 0, false) != nil {
		t.Fatal("detector matched a foreign run-id")
	}
}

