// RunID is the deterministic identity of one logical execution:
// hash(uid, generation, triggerInstance). Retries of the same logical run
// produce the same ID across operator restarts and API partitions.
func RunID(uid types.UID, generation int64, triggerInstance string) string {
	return hash12(uid, generation, triggerInstance)
}
